#include <bits/stdc++.h>
using namespace std;

int btd(long long n) {
    int decimalNumber = 0, power = 1;
    while (n != 0) {
        decimalNumber += (n % 10) * power;
        n /= 10;
        power *= 2;
    }
    return decimalNumber;
}

string dtb(int n) {
    if (n == 0) return "0";

    string result;
    while (n != 0) {
        result.push_back(char('0' + n % 2));
        n /= 2;
    }
    reverse(result.begin(), result.end());
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a, b;
    cin >> a >> b;

    int q = btd(a) ^ btd(b);
    string result = dtb(q);
    size_t length = to_string(a).size();

    if (result.size() < length) {
        result.insert(result.begin(), length - result.size(), '0');
    }

    cout << result;
    return 0;
}

